package com.farika.soundflow;
/** Shows only a provider-issued HTTPS challenge; completion is reported only by that iframe. No fabricated cookies or challenge solving. */
public final class ChallengeScript {
 private ChallengeScript(){}
 public static String build(String key,String url){if(!AuthCapture.challenge(url))throw new IllegalArgumentException("Unsupported challenge origin");return "(function(){'use strict';if(location.protocol!=='https:'||!['soundcloud.com','www.soundcloud.com','m.soundcloud.com'].includes(location.hostname))return false;const K="+AccountScript.quote(key)+",U="+AccountScript.quote(url)+";window[K]={pending:true};const f=document.createElement('iframe');f.src=U;f.title='Проверка SoundCloud';f.style.cssText='position:fixed;top:0;left:0;right:0;bottom:0;width:100%;height:100%;border:0;background:white;z-index:2147483647';function receive(e){try{if(e.source!==f.contentWindow)return;const o=new URL(e.origin);if(o.protocol!=='https:'||(o.port&&o.port!=='443')||!(o.hostname==='captcha-delivery.com'||o.hostname.endsWith('.captcha-delivery.com')))return;let d=e.data;if(typeof d==='string'){if(d.length>20000)return;d=JSON.parse(d);}if(!d||typeof d.cookie!=='string'||d.cookie.length>16384||!/^datadome=[^;\\s]+(?:;[^\\r\\n]*)?$/.test(d.cookie))return;document.cookie=d.cookie;const pair=d.cookie.split(';')[0];if(!document.cookie.split(';').some(function(c){return c.trim()===pair;}))return;window[K]={passed:true};window.removeEventListener('message',receive);f.remove();}catch(_){}}window.addEventListener('message',receive);document.body.appendChild(f);return true;})()";}
}
